def interval_stabbing(intervals):
    records = []
    for interval in intervals:
        if interval[0] > interval[1]:
            return None
        records.append([interval[1], interval[0]])
    records = ordered(records)
    points = []
    last = None
    for record in records:
        if last is None or last < record[1]:
            last = record[0]
            points.append(last)
    return points

