def greedy_change(coins, amount):
    if amount < 0:
        return None
    for coin in coins:
        if coin <= 0:
            return None
    values = ordered(coins)
    selected = []
    remaining = amount
    for index in range(len(values) - 1, -1, -1):
        coin = values[index]
        while remaining >= coin:
            remaining = remaining - coin
            selected.append(coin)
    return {"coins": selected, "remaining": remaining}

